    if not re.match(r"^[0-9]{1}[-]{2}[0-9]{3}[-]{4}[0-9,X]$", isbn):
        raise ValueError("Invalid ISBN number")

    # Calculate the ISBN checksum
    checksum = sum([int(digit) for digit in isbn[:-1]])

    # Determine the checksum digit
    if isbn[-1] == "X":
        checksum_digit = 10
    else:
        checksum_digit = int(isbn[-1])

    # Compare the checksums
    if checksum_digit == 10:
        if checksum % 11 == 0:
            return "Right"
        else:
