        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i, c in enumerate(original):
        if c not in mapping:
            mapping[c] = message[i]
        else:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for c in encoded:
        if c in mapping:
            decoded += mapping[c]
        else:
            return "Failed"

    return decoded

def decode(encoded, original, message):
    # Build the mapping from encoded to original letters
    char_map = {}
    for i, c in enumerate(original):
        char_map[encoded[i]] = c

    # Check for contradiction and completeness of the mapping
    for c in encoded:
        if char_map[c] in char_map.values():
            return "Failed"
    for c in original:
        if c not in char_map.values():
            return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for c in message:
        decoded += char_map[c]
    return decoded

